-- HSK 2 and HSK 3 vocabulary banks; 24 original items per level.
-- Each item asks for the Chinese word; all choices are in Chinese with pinyin displayed by EduAssess.
-- Distractors are other words from the same level. Safe to rerun.
begin;
on conflict (question_id) do update set level=excluded.level,skill=excluded.skill,item_type=excluded.item_type,prompt=excluded.prompt,stimulus=excluded.stimulus,options=excluded.options,answer_key=excluded.answer_key,explanation=excluded.explanation,audio_status=excluded.audio_status,source_reference=excluded.source_reference,is_published=excluded.is_published,updated_at=now();
commit;
select level,skill,count(*) as published_questions from public.hsk_questions where skill='vocabulary' and level in (2,3) and is_published=true group by level,skill order by level;